document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("search-help");if(!window.PagefindUI)return;t.hidden=!0;const n=new PagefindUI({element:"#search",showSubResults:!1,showImages:!1,resetStyles:!1,processResult(e){if(e.meta.intro){const t=document.createElement("span");t.textContent=e.meta.intro,e.excerpt=t.innerHTML,delete e.meta.intro}return e}}),e=new URLSearchParams(location.search).get("q");e&&n.triggerSearch(e)})